const esperado = "__WEBHOOK_TOKEN__";
const recebido = $input.first().json.headers?.['x-webhook-token'];
if (recebido !== esperado) {
  throw new Error('Token invalido');
}
return $input.all();

function render(tpl, vars) {
  return String(tpl || '').replace(/\{\{\s*(\w+)\s*\}\}/g, (m, k) =>
    k in vars ? String(vars[k]) : m
  );
}
function normalizePhone(v) {
  let d = String(v || '').replace(/\D/g, '');
  if (d.length === 12 || d.length === 13) {
    if (!d.startsWith('55')) return null;
    d = d.substring(2);
  }
  if (d.length !== 10 && d.length !== 11) return null;
  if (parseInt(d.substring(0, 2), 10) < 11) return null;
  if (d.length === 11 && d[2] !== '9') return null;
  return '55' + d;
}

const rows = $('Buscar Reserva').all().map(i => i.json).filter(r => r && r.id);
const booking = rows[0];
if (!booking) { return [{ json: { semDestinatario: true, motivo: 'Reserva nao encontrada' } }]; }

const todosTpl = $('Buscar Template').all().map(i => i.json).filter(r => r && r.message);
// O texto de todo mundo e o sem categoria. Nao cai para todosTpl[0]: a
// busca traz duas linhas, e pegar a errada mandaria o texto do
// responsavel para a reuniao inteira.
const tplRow = todosTpl.find(r => !r.category);
// Quem pediu a sala recebe um texto que reconhece o papel dele.
const tplResponsavel = todosTpl.find(r => r.category === 'responsavel');
const evento = $('Webhook').first().json.body.evento;
const ehCancelamento = evento === 'cancelamento';
const tplCancelamento = "Ola *{{nome_colaborador}}*! \u274c\n\nA reuniao abaixo foi *cancelada*:\n\n*Assunto:* {{titulo}}\n*Sala:* {{sala}}\n*Data:* {{data}}\n*Horario:* {{horario}}\n\n_Mensagem automatica da Portaria Inteligente._";
// Reserva so para o caso de o template nao estar no banco. Um por evento:
// cair no texto de convite numa alteracao diria "voce foi convidado" para
// quem so precisava saber que o horario mudou.
const tplAtualizacao = "Ola *{{nome_colaborador}}*! \u{1f504}\n\nA reuniao *{{titulo}}* foi alterada:{{mudou_data}}{{mudou_horario}}{{mudou_sala}}\n\nComo ficou:\n\n*Sala:* {{sala}}\n*Data:* {{data}}\n*Horario:* {{horario}}\n\n_Mensagem automatica da Portaria Inteligente._";
const tplAgendamento = 'Ola *{{nome_colaborador}}*! \u{1f4c5}\n\nVoce foi convidado(a) para uma reuniao:\n\n*Assunto:* {{titulo}}\n*Sala:* {{sala}}\n*Data:* {{data}}\n*Horario:* {{horario}}';
const tpl = tplRow?.message
  || (ehCancelamento ? tplCancelamento : evento === 'atualizacao' ? tplAtualizacao : tplAgendamento);

const sala = booking.rooms?.name || 'Sala';
const data = String(booking.booking_date).split('-').reverse().join('/');
const horario = String(booking.start_time).substring(0,5) + ' as ' + String(booking.end_time).substring(0,5);
// Linha do cafe: entra so quando a copa foi acionada. Vazia, a
// variavel {{cafe}} some do texto sem deixar buraco.
const cafe = booking.service === 'com_cafe' ? "\n\u2615 Servico de cafe solicitado." : '';

// Linhas do "o que mudou", so na atualizacao. Cada uma fica vazia quando
// aquele campo nao mudou, entao a mensagem conta so o que aconteceu \u2014 a
// tela ja filtra, mas o fluxo nao depende disso para montar o texto.
// O ~til~ e o tachado do WhatsApp: mostra o valor antigo riscado.
const anterior = $('Webhook').first().json.body.anterior || {};
function mudanca(rotulo, antes, agora) {
  if (!antes || antes === agora) return '';
  return "\n*" + rotulo + ":* ~" + antes + "~ \u2192 *" + agora + "*";
}
const mudou_data = mudanca('Data', anterior.data ? String(anterior.data).split('-').reverse().join('/') : '', data);
const mudou_horario = mudanca('Horario', anterior.horario, horario);
const mudou_sala = mudanca('Sala', anterior.sala, sala);

const out = [];
for (const p of (booking.booking_participants || [])) {
  const c = p.collaborators;
  if (!c) continue;
  const fone = normalizePhone(c.phone);
  if (!fone) continue;
  out.push({ json: {
    number: fone,
    text: render(
      (ehCancelamento && tplResponsavel && c.id === booking.responsavel_id)
        ? tplResponsavel.message
        : tpl,
      {
      nome_colaborador: c.name,
      titulo: booking.title,
      sala, data, horario,
      cafe,
      mudou_data, mudou_horario, mudou_sala,
    }),
  }});
}
// Reuniao sem participantes (ou sem telefone valido) nao e falha:
// nao ha a quem avisar. Devolver lista vazia travaria o fluxo — o n8n
// nao roda os nos seguintes — e o webhook responderia vazio, que a
// Edge Function leria como erro.
if (out.length === 0) {
  return [{ json: { semDestinatario: true, motivo: 'Nenhum participante com telefone' } }];
}
return out;

// Uma reuniao sem participantes nao e falha: nao ha a quem avisar.
// O marcador vem de Montar Mensagens porque o no de envio
// substitui o json pelo resultado (ou erro) da Evolution.
const origem = $('Montar Mensagens').all();
const semNinguem = origem.length === 1 && origem[0].json.semDestinatario;
if (semNinguem) {
  return [{ json: { success: true, enviados: 0, total: 0, motivo: origem[0].json.motivo } }];
}
const itens = $input.all();
const ok = itens.filter(i => !i.json.error).length;
return [{ json: { success: true, enviados: ok, total: itens.length } }];
